import{_ as i,o as a,c as s,a3 as l,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const t="/bilder/suchen-gruppenprozesse/gruppenprozesse-wiedervorlage.png",o="/bilder/suchen-gruppenprozesse/gp-eintrag-in-die-wiedervorlage.jpg",d="/bilder/suchen-gruppenprozesse/gp-ausfuehren.jpg",g="/bilder/suchen-gruppenprozesse/wiedervorlage-anzeigen.jpg",p="/bilder/suchen-gruppenprozesse/uebersicht-eintraege-in-der-wiedervorlage.jpg",z=JSON.parse('{"title":"Wiedervorlagen für eine Schülergruppe anlegen","description":"","frontmatter":{"title":"Wiedervorlagen für eine Schülergruppe anlegen","source_pageid":384,"source_revision":5325},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/eintrag-in-die-wiedervorlage-machen-gruppenprozesse-allgemein.md","filePath":"schild3/suchen-gruppenprozesse/eintrag-in-die-wiedervorlage-machen-gruppenprozesse-allgemein.md"}'),u={name:"schild3/suchen-gruppenprozesse/eintrag-in-die-wiedervorlage-machen-gruppenprozesse-allgemein.md"};function h(c,n,m,v,f,b){return a(),s("div",null,[...n[0]||(n[0]=[l('<h1 id="wiedervorlagen-fur-eine-schulergruppe-anlegen" tabindex="-1">Wiedervorlagen für eine Schülergruppe anlegen <a class="header-anchor" href="#wiedervorlagen-fur-eine-schulergruppe-anlegen" aria-label="Permalink to &quot;Wiedervorlagen für eine Schülergruppe anlegen&quot;">​</a></h1><p>Wiedervorlagen erinnern an spätere Aufgaben für eine ausgewählte Schülergruppe. Die Anleitung beschreibt die Einrichtung; das Video ergänzt die einzelnen Arbeitsschritte.</p><h2 id="wiedervorlage-einrichten" tabindex="-1">Wiedervorlage einrichten <a class="header-anchor" href="#wiedervorlage-einrichten" aria-label="Permalink to &quot;Wiedervorlage einrichten&quot;">​</a></h2><p>Legen Sie eine Wiedervorlage mit Bemerkung und Termin für mehrere Schülerinnen und Schüler an. Bestimmen Sie Sichtbarkeit und Verhalten nach Ablauf des Termins.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-wiedervorlage.png"><img src="'+t+'" alt="Manuelles Setzen der Wiedervorlage bei einem Schüler." loading="lazy"></a></p><p><em>Manuelles Setzen der Wiedervorlage bei einem Schüler.</em></p><p>Einträge zur Wiedervorlage können bei einzelnen Schülerinnen und Schülern über einen Klick auf das <strong>Weckersymbol</strong> bei den <em>Individualdaten I</em> hinzugefügt werden.</p><p><a href="/bilder/suchen-gruppenprozesse/gp-eintrag-in-die-wiedervorlage.jpg"><img src="'+o+'" alt="Auswahl des Gruppenprozesses" loading="lazy"></a></p><p><em>Auswahl des Gruppenprozesses</em></p><p>Einträge zur Wiedervorlage können aber auch gruppenweise vorgenommen werden. Nach der Schülerauswahl über den Schnellfilter (Klasse, Jahrgang, Kurs), oder die Auswahl, wird im Auswahlmenü <em>Gruppenprozesse</em> in der Kategorie <em>Allgemeines</em> der Prozess <strong>Eintrag in Wiedervorlage machen</strong> angeklickt.</p><p>Im Menü, das nun rechts erscheint, kann eine <em>Bemerkung zur Wiedervorlage</em> eingegeben und der Wiedervorlagetermin ausgewählt werden.</p><p>Darüber hinaus kann durch das Setzen der entsprechenden Häkchen festgelegt werden, ob der Eintrag auch <em>für das Sekretariat sichtbar</em> sein soll. Andernfalls kann ihn nur die Nutzerin / der Nutzer sehen die/der den Eintrag angelegt hat.</p><p>Weiterhin ist anzugeben, ob die Wiedervorlage nach dem Ablaufdatum gelöscht werden oder erhalten bleiben soll.</p><p><a href="/bilder/suchen-gruppenprozesse/gp-ausfuehren.jpg"><img src="'+d+'" alt="Gruppenprozess ausführen" loading="lazy"></a></p><p><em>Gruppenprozess ausführen</em></p><p>Über &quot;Prozess ausführen&quot; wird der Vorgang angestoßen und die jeweiligen Eintragungen werden vorgenommen.</p><p><a href="/bilder/suchen-gruppenprozesse/wiedervorlage-anzeigen.jpg"><img src="'+g+'" alt="Wiedervorlage aufrufen" loading="lazy"></a></p><p><em>Wiedervorlage aufrufen</em></p><p>Die neuen Einträge können dann im Auswahlmenü <em>Schüler</em> über <strong>Wiedervorlage ansehen</strong> eingesehen werden.</p><p><a href="/bilder/suchen-gruppenprozesse/uebersicht-eintraege-in-der-wiedervorlage.jpg"><img src="'+p+'" alt="Einträge in der Wiedervorlage" loading="lazy"></a></p><p><em>Einträge in der Wiedervorlage</em></p><p>Einträge zur Wiedervorlage erscheinen nur, wenn ein Datum nach dem gesetzten Wiedervorlagedatum ausgewählt wurde.</p>',22),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,"Beim Erst-Start von SchILD an einem nächstfolgenden Tag werden die Wiedervorlage-Einträge mit dem Tages-Datum angezeigt. Das Fenster Fenster entspricht dem hier abgebildeten.")],-1),e("hr",null,null,-1),e("h2",{id:"videotutorial",tabindex:"-1"},[r("Videotutorial "),e("a",{class:"header-anchor",href:"#videotutorial","aria-label":'Permalink to "Videotutorial"'},"​")],-1),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/8hKaUTORfpU?",frameborder:"0",allowfullscreen:""},null,-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Eintrag_in_die_Wiedervorlage_machen_(Gruppenprozesse_Allgemein)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),r(" · Quellrevision 5325.")],-1)])])}const _=i(u,[["render",h]]);export{z as __pageData,_ as default};
